# -*- coding: utf-8 -*-
"""矛盾驱动补盲 · 批次C8（v6 新域 8 簇+直答）"""
def patch(path):
    src = open(path, encoding="utf-8").read()
    anchor_c = '    "概念形成": ["概念形成", "原型理论", "样例理论", "概念是怎么形成的"],'
    new_c = '''    "法律维权": ["维权难", "维权贵", "打官司值得吗", "被坑了", "费时费力",
                "忍一忍更划算", "法律给有钱人", "普通人维权", "低成本维权",
                "值不值得打官司", "维权成本", "打官司", "起诉", "消费者维权"],
    "疫苗犹豫": ["不愿打疫苗", "强制防疫", "侵犯自由", "不打疫苗自由",
                "害了别人", "疫苗副作用", "被隐瞒", "疫苗犹豫", "打疫苗",
                "防疫措施", "接种", "疫苗安全"],
    "容貌焦虑": ["容貌焦虑", "不漂亮没人喜欢", "变美有错", "精致有错",
                "矫情", "摆脱容貌焦虑", "医美", "整容", "滤镜",
                "外貌焦虑", "丑", "长相"],
    "城市孤独": ["越长大越孤独", "空巢青年", "一个人也挺好", "刻意社交",
                "孤独是常态", "和孤独相处", "真心的朋友", "孤独感",
                "社恐", "没朋友", "孤单"],
    "留学选择": ["送孩子留学", "留学值不值", "国外教育更好", "留学白花钱",
                "该不该留学", "留学真正价值", "留学", "出国留学",
                "留学的回报", "留学回来", "出国读书"],
    "人脸识别": ["到处装人脸识别", "刷脸安全", "没有监控坏人", "怕监控",
                "无处不在的监控", "人脸识别", "刷脸", "监控",
                "摄像头", "面部识别"],
    "深度伪造": ["AI换脸视频", "识别视频假的", "换脸娱乐", "技术无罪",
                "用的人有罪", "防范深度伪造", "深度伪造", "AI换脸",
                "假视频", "伪造视频", "换脸"],
    "防灾准备": ["河边建房", "地震带建房", "防灾投入不够", "资源防灾",
                "发展和防灾", "家庭应急准备", "防灾", "应急准备",
                "自然灾害", "防汛", "地震防范", "应急物资"],'''
    assert anchor_c in src
    src = src.replace(anchor_c, new_c + "\n    " + anchor_c, 1)

    anchor_d = '    "概念形成": "概念形成是人获得概念的方式——原型理论（典型样例）、样例理论（具体实例）、理论观（嵌入知识网络）；对应知识卡组织",'
    new_d = '''    "法律维权": "维权难，是『法律程序成本』vs『个体损失』的不对称——打官司要时间（一审半年起）、金钱（律师费/诉讼费）、精力（举证/出庭），而普通纠纷的标的往往几千几万块，成本可能超过损失。真相：①『忍一忍更划算』是多数人的理性选择——不是法治没希望，是程序成本确实高（小额诉讼/调解本是解药但宣传不够）；②『法律给有钱人』半真半假——富人用得起律师是事实，但法律援助/小额诉讼/公益诉讼也在兜底，普通人不是完全无助；③被坑要不要打官司——先算三笔账：金额账（标的≥诉讼成本2倍才划算）、证据账（有合同/记录/聊天=有戏，口头承诺=难）、时间账（你耗得起吗）。低成本维权三招：①先协商留痕——正式书面沟通（邮件/函件）比口头强（对方怕留证据）；②找免费通道——12315/消协/劳动仲裁（不收费且程序快）/平台投诉（有赔付机制）；③小额仲裁——金额小的选仲裁不选诉讼（快很多）。核心：维权不是非黑即白——能协商的不诉讼，能仲裁的不上庭，成本可控才坚持",
    "疫苗犹豫": "疫苗犹豫和防疫争议，是『公共健康收益』vs『个体自主/担忧』的矛盾——疫苗/防疫保护的是群体（群体免疫），代价由个体承担（副作用风险/自由受限），收益和成本主体分离，必然有张力。真相：①不愿打疫苗的多元原因——不是都反智：有人怕副作用（信息不足）、有人不信（权威信任度低）、有人嫌麻烦（便利性）、有人真不适合（禁忌症），一竿子打成『愚昧』只会强化对立；②『不打疫苗的自由会不会害别人』——会：疫苗不只是保护自己（防重症），更是减少传播（保护无法接种的弱势群体：婴儿/免疫缺陷者），所以自由有边界（你的自由止于别人的健康）；③副作用被隐瞒？——副作用真实存在（绝大多数轻微），但『隐瞒』是阴谋论：疫苗审批有公示数据，只是风险沟通做得差（只宣传收益不讲风险→发现风险后信任崩塌）。平衡：①沟通优先——讲清收益和风险（不夸大不隐瞒），尊重知情权；②强制留口——强制接种要有豁免通道（医学禁忌/宗教），硬来适得其反；③信任重建——权威机构要透明（不良反应及时公布），遮掩才是谣言土壤",
    "容貌焦虑": "容貌焦虑，是『社会审美标准』vs『真实自我接纳』的矛盾——滤镜/修图/审美工业制造『标准美』（大眼睛/白瘦/无瑕），现实的人永远够不到标准，于是焦虑。真相：①不漂亮没人喜欢是认知扭曲——喜欢你的朋友家人是因为『你是你』（性格/陪伴/记忆），不是脸；社交中『好看』是加分项但不是入场券，性格/能力/真诚才是长久的；②变美/精致有错吗——没错：追求更好的自己是正当的，问题是『为谁而美』：为自己的愉悦是自我照顾，为别人的眼光是自我惩罚（焦虑的边界在这里）；③容貌焦虑不是矫情——是真实痛苦：审美压力从社交媒体渗透进现实（连孩子都开始外貌比较），焦虑是环境的产物不是脆弱。摆脱三招：①信息减毒——取关制造焦虑的账号（过度修图/身材贩卖），刷『素颜/真实』内容对冲；②转移焦点——把注意力从『看起来如何』移到『我能做什么』（技能/爱好/关系），自我价值感锚在能力上比锚在外表稳；③医美/整容怎么看——把整容当『手术』不当『美容』：风险（失败/后遗症）和花费是真实代价，能接纳自己就不需要，非要改善选正规机构+为悦己不为悦人",
    "城市孤独": "越长大越孤独，是『城市化原子化』vs『归属需要』的矛盾——城市把熟人社会打散成陌生人社会（邻里不相识/同事下班即散），人成了原子，孤独是结构的产物不是你的失败。真相：①空巢青年的孤独——一个人住/点外卖/刷手机，『物理独处』+『情感无连接』：不是没人，是没『深度关系』（可倾诉/可依靠的人）；②『一个人也挺好』半真——独处能力是好的（自洽），但『习惯了孤独』可能是防御（怕受伤所以不靠近），长期无深度连接的人幸福感显著更低；③孤独是常态吗——是城市常态，但『接受常态』≠『放弃连接』：孤独感是信号（需要连接），忽视信号会抑郁。破局三招：①从『找朋友』到『建连接』——朋友不是找来的是一起做事长出来的（共同兴趣社群/运动/读书会/志愿活动），先有共同活动后有友谊；②定期深度交流——和2-3个信任的人固定深聊（家人/老友），弱连接（点赞之交）不能替代深度倾诉；③和孤独相处的能力——独处时做滋养的事（读书/创作/运动）而不是空虚刷手机，孤独时『做点什么』比『想为什么孤独』有用。核心：孤独是城市的常态，连接是主动的选择——两者可以并存",
    "留学选择": "留学值不值，是『高成本投入』vs『不确定回报』的矛盾——花几十万出国，回报可能是视野/学历/人脉（隐性），也可能只是『镀金』（回国工资没高多少）。真相：①留学值不值没有统一答案——取决于目的：为学历（看学校排名/专业含金量）、为视野（体验不同文化/独立生活）、为移民（看政策）、为逃避（国内没考上→出去混，不值）；②『国外教育更好』是刻板印象——国外强在批判性思维/自主研究/多元评价，弱在基础教育（数学/语文扎实度不如国内），各有所长；③『白花钱』的真相——留学回报率分化严重：名校热门专业（CS/金融）回报高，普通学校水专业回报低，『留学回来找不到工作』多是后者（学历贬值的是水硕不是留学）。判断该不该留学：①目的明确吗——想清楚为学历/视野/移民的哪一个（逃避不算）；②家庭财务——留学是投资不是消费：家里能承受（不卖房不借贷）才去，砸锅卖铁去读水硕不值得；③可替代方案——国内考研/中外合作/网课名校，同样能达到目的就不必花大钱。真正价值：留学最大的收获是『独立』（一个人处理一切）+『视角』（站在另一种文化里看自己），这些是无形的，但比学历标签更持久",
    "人脸识别": "到处装人脸识别，是『安全/便利』vs『隐私/滥用』的矛盾——刷脸方便（支付/门禁/通行），但脸是不可更换的生物特征（密码能改，脸不能改），一旦泄露就是终身风险。真相：①刷脸真的安全吗——半真：识别技术本身强（活体检测防照片），风险不在识别在『数据』：你的脸被存哪里/谁能调/怎么用（人脸数据库一旦泄露或被滥用，你没有第二张脸）；②『没有监控坏人怎么抓』——监控确实破案利器（天网），但『监控抓坏人』和『人人被监控』是两回事：没有程序约束的监控会变成控制工具（你是谁/去哪/和谁，全被记录）；③『没干坏事怕什么』——这是最危险的逻辑：隐私保护的正是『不想被知道的部分』（合法但私密），今天你没事，明天政策变了呢？平衡之道：①分场景使用——公共安全（抓逃犯）可用，商业场景（刷脸进店/卖数据）慎用，『必要+最小化』（只采集必要信息/限时保存）；②立法透明——监控要公示（哪里装/为什么/数据谁管），公民有知情权和删除权；③个人防护——能不用刷脸就不用（支付选密码/门禁用卡），关键账户别绑人脸。核心：监控是工具不是目的——为安全可以，为控制不行，透明和边界是底线",
    "深度伪造": "AI换脸/深度伪造，是『技术便利』vs『真实可信』的矛盾——合成技术让假视频以假乱真（明星换脸/领导讲话/亲友求助），真相和名誉都受威胁。真相：①为什么危险——不是换脸娱乐本身，是『伪造的杀伤力』：假视频诈骗（冒充亲友借钱/领导指示转账）、名誉毁灭（伪造色情/违法视频毁人）、舆论操纵（制造假新闻影响选举/股价）；②『换脸只是娱乐』——娱乐只是冰山一角，水下是诈骗/抹黑/操纵，你看到的是乐子，骗子看到的是工具；③『技术无罪用的人有罪』——技术中立论对但不够：平台明知可伪造却不标识/不检测，等于帮凶；立法要管的是『用』（伪造传播违法）和『不标注』（合成内容必须标识）。防范三招：①识别技巧——看细节（眨眼频率/嘴唇同步/边缘闪烁/光线阴影），关键视频多角度验证（打电话确认，别信视频）；②平台责任——要求合成内容强制标注（AI生成水印），社交平台要有检测机制（假视频标红/限流）；③立法+自保——伪造他人违法（追责），保护自己：关键信息多因素验证（视频里的『本人』也要电话确认）。核心：技术可以伪造一切，所以『验证』成为新习惯——重要的事，别只看一个视频",
    "防灾准备": "明知道有风险还在河边/地震带建房，是『生存发展』vs『安全』的矛盾——河边/平原/沿海是经济发展区（水运/耕地/城市），自然灾害风险区往往也是人口经济密集区（风险是发展积累出来的）。真相：①为什么还在风险区建房——不是不知道危险，是『没得选』：家乡在那/地便宜/生活在那（穷人更可能住在风险区，富人搬走了），加上『风险概率低』心理（百年一遇=觉得自己遇不上）；②防灾投入总是不够——投入产出不对等：防灾的钱平时看不见收益（没灾害=白花），政绩显示度低，所以『事后救灾』比『事前防灾』更容易获得拨款（这是全球通病不是中国特有）；③『天灾躲不过防了白防』——错：灾害防不住但损失可防（日本地震烈度8级损失远小于同等级其他地区，防震建筑/预警系统/应急演练真能救命）。平衡与准备：①个人——选址避开高风险区（能选就选），加固住房（抗震/防洪标准），备应急包（水/食物/药品/手电/证件，放门口）；②家庭预案——约定集合点/应急联系人/逃生路线，一年演练一次（灾害时慌不乱）；③社会——防灾投入是『保险思维』：平时交点『保费』（防灾预算），灾害时省大钱（重建成本远高于预防），预警系统/避难所/教育是性价比最高的投资。核心：防灾不是对抗自然，是降低损失——准备得越充分，风险越接近『可控』",
    "概念形成": "概念形成是人获得概念的方式——原型理论（典型样例）、样例理论（具体实例）、理论观（嵌入知识网络）；对应知识卡组织",'''
    assert anchor_d in src
    src = src.replace(anchor_d, new_d, 1)
    open(path, "w", encoding="utf-8").write(src)
    print("patched")

